import { View, Text, Pressable, ActivityIndicator, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

// Эхний дуудлага алдаа өгч, дараагийнх нь амжилттай (сервер сэргэсэн гэж бод).
let attempts = 0;
const fakeApi = () => new Promise((res, rej) => setTimeout(() => {
  attempts += 1;
  if (attempts === 1) rej(new Error("Сүлжээний алдаа"));
  else res([{ id: "p1", name: "Чихэвч" }, { id: "p2", name: "Гар цаг" }]);
}, 200));

function App() {
  const [items, setItems] = useState(null);
  const [error, setError] = useState(false);

  function load() {
    setError(false);
    setItems(null);
    fakeApi()
      .then((data) => setItems(data))
      .catch(() => setError(true));
  }
  useEffect(() => { load(); }, []);

  if (error) {
    return (
      <View style={styles.center}>
        <Text nativeID="err" style={styles.err}>Ачаалж чадсангүй</Text>
        {/* энд бичнэ үү: load()-г дахин дуудах "Дахин оролдох" Pressable товч */}
      </View>
    );
  }
  if (items === null) return <View style={styles.center}><ActivityIndicator size="large" /></View>;
  return (
    <View style={styles.list}>
      {items.map((it) => <Text key={it.id} testID="row" style={styles.row}>{it.name}</Text>)}
    </View>
  );
}

const styles = StyleSheet.create({
  center: { flex: 1, alignItems: "center", justifyContent: "center", gap: 14 },
  err: { fontSize: 16, color: "#dc2626" },
  btn: { backgroundColor: "#2563eb", paddingHorizontal: 20, paddingVertical: 12, borderRadius: 10 },
  btnText: { color: "#fff", fontWeight: "bold" },
  list: { flex: 1, padding: 16 },
  row: { fontSize: 16, paddingVertical: 12, borderBottomWidth: 1, borderColor: "#e2e8f0" },
});

registerRootComponent(App);

